script:
(function () {
  'use strict';
  // Side-by-side comparison of up to three fixed-rate, monthly-payment loans.
  //   Payment: M = L * i / (1 - (1 + i)^-n), i = rate / 12, n = round(years * 12); M = L / n at 0%.
  //   Total interest = M * n - L.  Total cost of borrowing = total interest + upfront fees.
  //   APR (fees included): the annual rate 12 * j where j solves
  //     (L - fees) = M * (1 - (1 + j)^-n) / j, found by bisection (US actuarial method).
  // Verified in Node (scratchpad tests/w2loans): $100,000 at 6% for 10 years = $1,110.21/mo and
  //   with $2,500 of fees APR = 6.563% (matches a published APR calculator's default); with no
  //   fees APR equals the note rate; $25,000 at 0% for 5 years = $416.67/mo and APR 0% without
  //   fees; the cheapest loan is picked by total cost; blank or negative input shows an error.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var KEYS = ['A', 'B', 'C'];

  function el(id) { return document.getElementById(id); }

  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function payment(principal, i, n) {
    if (n <= 0 || principal <= 0) return 0;
    if (i === 0) return principal / n;
    return principal * i / (1 - Math.pow(1 + i, -n));
  }

  function pv(pmt, j, n) { return j === 0 ? pmt * n : pmt * (1 - Math.pow(1 + j, -n)) / j; }

  // Monthly rate j at which the payments are worth exactly the cash received.
  function solveApr(net, pmt, n) {
    if (net <= 0 || pmt <= 0) return NaN;
    if (net >= pmt * n - 1e-9) return 0;
    var lo = 0, hi = 1;
    while (pv(pmt, hi, n) > net && hi < 1e6) hi *= 2;
    for (var k = 0; k < 200; k++) {
      var mid = (lo + hi) / 2;
      if (pv(pmt, mid, n) > net) lo = mid; else hi = mid;
    }
    return 12 * (lo + hi) / 2;
  }

  function analyse(amount, ratePct, years, fees) {
    var n = Math.round(years * 12), i = ratePct / 100 / 12;
    var pmt = payment(amount, i, n);
    var interest = Math.max(0, pmt * n - amount);
    return { amount: amount, rate: ratePct, n: n, pmt: pmt, interest: interest, fees: fees,
             cost: interest + fees, paid: pmt * n + fees, apr: solveApr(amount - fees, pmt, n) };
  }

  function setText(id, text) { el(id).textContent = text; }

  function clearResults() {
    ['lqBestCost', 'lqBestPay', 'lqSaving'].forEach(function (id) { setText(id, '–'); });
    setText('lqVerdict', '');
    el('lqTable').innerHTML = '';
  }

  function aprText(a) { return isNaN(a) ? 'n/a' : (a * 100).toFixed(3) + '%'; }

  function update() {
    var useC = el('lqUseC').checked;
    el('lqSetC').disabled = !useC;
    var keys = useC ? KEYS : KEYS.slice(0, 2), loans = [], msg = '';
    keys.forEach(function (k) {
      if (msg) return;
      var amount = read('lqAmount' + k), rate = read('lqRate' + k), years = read('lqTerm' + k), fees = read('lqFees' + k, true);
      if (isNaN(amount) || amount <= 0) msg = 'Enter a loan amount greater than $0 for loan ' + k + '.';
      else if (isNaN(rate) || rate < 0 || rate > 100) msg = 'Enter an interest rate from 0% to 100% for loan ' + k + '.';
      else if (isNaN(years) || years <= 0 || years > 40 || Math.round(years * 12) < 1) msg = 'Enter a term from 1 month to 40 years for loan ' + k + '.';
      else if (isNaN(fees) || fees < 0) msg = 'Fees for loan ' + k + ' cannot be negative.';
      else if (fees >= amount) msg = 'Fees for loan ' + k + ' must be less than the loan amount.';
      else { var r = analyse(amount, rate, years, fees); r.key = k; loans.push(r); }
    });
    var error = el('lqError');
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) { clearResults(); return; }

    var byCost = loans.slice().sort(function (a, b) { return a.cost - b.cost; });
    var byPay = loans.slice().sort(function (a, b) { return a.pmt - b.pmt; });
    var best = byCost[0], worst = byCost[byCost.length - 1], low = byPay[0];
    setText('lqBestCost', 'Loan ' + best.key + ' · ' + money.format(best.cost));
    setText('lqBestPay', 'Loan ' + low.key + ' · ' + money.format(low.pmt));
    setText('lqSaving', money.format(worst.cost - best.cost));
    var verdict;
    if (worst.cost - best.cost < 0.005) verdict = 'All the loans cost the same to borrow in total.';
    else if (low.key === best.key) verdict = 'Loan ' + best.key + ' has both the lowest monthly payment and the lowest total cost.';
    else verdict = 'Loan ' + low.key + ' has the lowest monthly payment, but over its life it costs ' +
      money.format(low.cost - best.cost) + ' more than loan ' + best.key + '.';
    if (loans.some(function (l) { return Math.abs(l.amount - loans[0].amount) > 0.005; }))
      verdict += ' The loan amounts differ, so compare the APRs as well as the dollar totals.';
    setText('lqVerdict', verdict);

    el('lqHead').innerHTML = '<tr><th scope="col">Item</th>' + loans.map(function (l) {
      return '<th scope="col">Loan ' + l.key + '</th>';
    }).join('') + '</tr>';
    var rows = [
      ['Loan amount', function (l) { return money.format(l.amount); }],
      ['Interest rate', function (l) { return l.rate.toFixed(2) + '%'; }],
      ['Number of monthly payments', function (l) { return String(l.n); }],
      ['Monthly payment', function (l) { return money.format(l.pmt); }],
      ['Total interest', function (l) { return money.format(l.interest); }],
      ['Upfront fees', function (l) { return money.format(l.fees); }],
      ['Total cost of borrowing', function (l) { return money.format(l.cost); }],
      ['Total paid (payments + fees)', function (l) { return money.format(l.paid); }],
      ['APR including fees', function (l) { return aprText(l.apr); }]
    ];
    el('lqTable').innerHTML = rows.map(function (row) {
      return '<tr><th scope="row">' + row[0] + '</th>' + loans.map(function (l) { return '<td>' + row[1](l) + '</td>'; }).join('') + '</tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('lqForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
